function geolocationError(error){const messages={1:'Localização bloqueada. No navegador, clique no ícone ao lado do endereço e escolha Permitir.',2:'O dispositivo não encontrou sua posição. Ative a Localização nas configurações do Windows ou celular.',3:'O GPS demorou para responder. Verifique o sinal e tente novamente.'},message=messages[error?.code]||'Não foi possível obter sua localização.';toast(message);const card=$('weatherCard');if(card){card.querySelector('span:not(.weather-icon)').textContent='GPS indisponível';card.querySelector('small').textContent=message}return message}
async function requestInitialLocation(){if(!window.isSecureContext&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1'){geolocationError({code:1});return}try{const permission=await navigator.permissions?.query({name:'geolocation'});if(permission?.state==='denied'){geolocationError({code:1});return}}catch{}try{await currentLocation({center:true});if(passiveLocationWatchId===null&&navigator.geolocation)passiveLocationWatchId=navigator.geolocation.watchPosition(value=>renderUserLocation(normalizeBrowserPosition(value),{center:false}),()=>{},{enableHighAccuracy:true,timeout:20000,maximumAge:3000})}catch{}}
