async function loadAccount(){const response=await fetch('/api/auth/me');if(response.status===401){location.replace('/login.html');return}const data=await response.json();if($('accountName'))$('accountName').textContent=data.user.name;if($('accountEmail'))$('accountEmail').textContent=data.user.email}
function haversine(a,b){const R=6371000,r=x=>x*Math.PI/180,d1=r(b.latitude-a.latitude),d2=r(b.longitude-a.longitude),q=Math.sin(d1/2)**2+Math.cos(r(a.latitude))*Math.cos(r(b.latitude))*Math.sin(d2/2)**2;return 2*R*Math.asin(Math.sqrt(q))}
function accuracyLabel(m){return m<=5?'Excelente':m<=15?'Boa':m<=50?'Moderada':'Baixa'}
async function loadRoadEvents(center,force=false){if(!roadEventsEnabled||!center)return;if(!force&&lastRoadEventLoad&&haversine(lastRoadEventLoad,center)<1000)return;roadEventRequest?.abort();roadEventRequest=new AbortController();try{const response=await fetch(`/api/road-events?lat=${center.latitude}&lng=${center.longitude}&radius=7000&categories=speed_camera,mobile_camera,traffic_light_camera,speed_bump,toll`,{signal:roadEventRequest.signal}),data=await response.json();if(!response.ok)throw new Error(data.error);layers.roadEvents.clearLayers();data.events.forEach(event=>L.circleMarker([event.latitude,event.longitude],{radius:event.category==='speed_bump'?5:7,color:'#fff',weight:2,fillColor:event.category==='toll'?'#1684e8':event.category==='speed_bump'?'#eaa514':'#e33b2f',fillOpacity:.95}).bindPopup(`<b>${escapeHtml(event.label)}</b><br>${event.speedLimit?`Limite: ${event.speedLimit} km/h<br>`:''}${formatDistance(event.distanceMeters)}`).addTo(layers.roadEvents));lastRoadEventLoad={latitude:center.latitude,longitude:center.longitude}}catch(error){if(error.name!=='AbortError')toast(error.message||'Eventos viários indisponíveis.')}}
window.addEventListener('rastreon:road-events-toggle',event=>{roadEventsEnabled=event.detail.enabled;if(!roadEventsEnabled){layers.roadEvents.clearLayers();return}const current=positions.at(-1),center=map.getCenter();loadRoadEvents(current||{latitude:center.lat,longitude:center.lng},true)});
window.addEventListener('rastreon:route-deviation',event=>rerouteFrom(event.detail.position));
