function renderTimelineEvents(){const hourly={};for(let i=1;i<positions.length;i++){const p=positions[i],prev=positions[i-1],key=new Date(p.timestamp).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit'}),meters=haversine(prev,p);if(meters<2000)hourly[key]=(hourly[key]||0)+meters}const avg=vehicle?1/(.55/vehicle.city+.45/vehicle.road):10,hours=Object.entries(hourly).map(([h,m])=>`<div class="event-item"><b>${escapeHtml(h)}h · ${formatDistance(m)}</b><small>Consumo estimado nesta hora: ${br(m/1000/avg,3)} L</small></div>`).join('');const eventHtml=events.map(e=>`<div class="event-item ${e.alert?'alert':''}"><b>${escapeHtml(e.title)}</b><small>${new Date(e.time).toLocaleString('pt-BR')} · ${escapeHtml(e.detail)}</small></div>`).join('');$('eventTimeline').innerHTML=(eventHtml||'<div class="empty-state">Inicie uma viagem para registrar eventos por hora.</div>')+(hours?`<div class="step-label">Distância e consumo por hora</div>${hours}`:'')}
function addEvent(title,detail='',alert=false,time=Date.now()){events.unshift({title,detail,alert,time});renderTimelineEvents()}
function setPoint(type,point,label){const oldMarker=type==='origin'?originMarker:destinationMarker;if(oldMarker)layers.points.removeLayer(oldMarker);const marker=L.marker([point.latitude,point.longitude]).addTo(layers.points).bindPopup(label);if(type==='origin'){origin=point;originMarker=marker;$('originInput').value=label}else{destination=point;destinationMarker=marker;$('destinationInput').value=label}}
async function geocode(inputId,resultId,type){const q=$(inputId).value.trim(),box=$(resultId);if(q.length<3)return;box.replaceChildren();const loading=document.createElement('button');loading.disabled=true;loading.textContent='Buscando…';box.appendChild(loading);box.classList.remove('hidden');try{const res=await fetch(`/api/geocode?q=${encodeURIComponent(q)}`),data=await res.json();if(!res.ok)throw new Error(data.error);box.replaceChildren();for(const [index,place] of data.entries()){const button=document.createElement('button');button.dataset.index=index;button.textContent=place.label;button.onclick=()=>{setPoint(type,place,place.label);box.classList.add('hidden')};box.appendChild(button)}if(!data.length){const empty=document.createElement('button');empty.disabled=true;empty.textContent='Nenhum endereço encontrado';box.appendChild(empty)}}catch(e){box.replaceChildren();const error=document.createElement('button');error.disabled=true;error.textContent=e.message||'Não foi possível buscar o endereço.';box.appendChild(error)}}
function debounce(fn,ms=450){let t;return(...args)=>{clearTimeout(t);t=setTimeout(()=>fn(...args),ms)}}
function renderStops(){const box=$('routeStops');box.innerHTML=routeStops.map((stop,index)=>`<div class="route-stop"><input data-stop-input="${index}" value="${escapeHtml(stop.label||'')}" placeholder="Parada ${index+1}: busque e pressione Enter"><button type="button" data-stop-up="${index}" ${index===0?'disabled':''}>↑</button><button type="button" data-stop-down="${index}" ${index===routeStops.length-1?'disabled':''}>↓</button><button type="button" data-stop-remove="${index}">×</button></div>`).join('');box.querySelectorAll('[data-stop-input]').forEach(input=>input.onkeydown=async event=>{if(event.key!=='Enter')return;event.preventDefault();const index=Number(input.dataset.stopInput),query=input.value.trim();if(query.length<3)return toast('Digite ao menos 3 caracteres para buscar a parada.');try{const response=await fetch(`/api/geocode?q=${encodeURIComponent(query)}`),places=await response.json();if(!response.ok)throw new Error(places.error);if(!places.length)throw new Error('Parada não encontrada.');routeStops[index]={...places[0],label:places[0].label};renderStops();toast('Parada localizada.')}catch(error){toast(error.message)}});box.querySelectorAll('[data-stop-remove]').forEach(button=>button.onclick=()=>{routeStops.splice(Number(button.dataset.stopRemove),1);renderStops()});box.querySelectorAll('[data-stop-up]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.stopUp);[routeStops[index-1],routeStops[index]]=[routeStops[index],routeStops[index-1]];renderStops()});box.querySelectorAll('[data-stop-down]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.stopDown);[routeStops[index+1],routeStops[index]]=[routeStops[index],routeStops[index+1]];renderStops()})}
function addStop(){if(routeStops.length>=8)return toast('Use no máximo 8 paradas.');routeStops.push({label:'',latitude:null,longitude:null});renderStops();$('routeStops').querySelector('[data-stop-input]:last-of-type')?.focus()}
function routeQuery(from,to){const validStops=routeStops.filter(stop=>Number.isFinite(stop.latitude)&&Number.isFinite(stop.longitude)),waypoints=validStops.map(stop=>`${stop.longitude},${stop.latitude}`).join(';');return`from=${from}&to=${to}&waypoints=${encodeURIComponent(waypoints)}&avoidTolls=${$('avoidTolls').checked}&vehicleType=${vehicle?.type==='motorcycle'?'motorcycle':'car'}&departureTime=${encodeURIComponent(new Date().toISOString())}`}
async function calculateRoute(){if(!origin||!destination)return toast('Selecione origem e destino nas sugestões ou no mapa.');if(routeStops.some(stop=>!Number.isFinite(stop.latitude)))return toast('Busque e confirme todas as paradas antes de calcular.');$('calculateBtn').disabled=true;$('calculateBtn').textContent='Calculando na malha viária…';try{const from=`${origin.longitude},${origin.latitude}`,to=`${destination.longitude},${destination.latitude}`,res=await fetch(`/api/route?${routeQuery(from,to)}`),data=await res.json();if(!res.ok)throw new Error(data.error);plannedRoutes=data.routes;renderRoutes(0);$('routeSummary').classList.remove('hidden');$('startNavigationBtn').disabled=false;$('alternativeCount').textContent=Math.max(0,data.routes.length-1);let provider=$('routeProvider');if(!provider){provider=document.createElement('small');provider.id='routeProvider';$('routeSummary').appendChild(provider)}provider.textContent=`Provider: ${data.source} · trânsito: ${data.traffic==='available'?'considerado':'indisponível'} · pedágios: ${data.tolls==='unavailable'?'indisponíveis':data.tolls==='avoided'?'evitados':'consultados'}`;toast(`${data.routes.length} rota(s) encontrada(s) por ${data.source}.`)}catch(e){toast(e.message)}finally{$('calculateBtn').disabled=false;$('calculateBtn').textContent='Calcular rota rodoviária'}}
async function rerouteFrom(position){if(!destination)return;toast('Desvio confirmado. Recalculando rota…');try{const from=`${position.longitude},${position.latitude}`,to=`${destination.longitude},${destination.latitude}`,response=await fetch(`/api/route?${routeQuery(from,to)}`),data=await response.json();if(!response.ok)throw new Error(data.error);origin={...position};plannedRoutes=data.routes;dailyNavigationMeters=0;lastDailyPosition=position;renderRoutes(0,false);navigation.start();navigation.update(position,Math.max(0,position.speed||0)*3.6,0);toast('Nova rota calculada a partir da sua posição.')}catch(error){toast(error.message||'Não foi possível recalcular a rota.')}}
function renderRoutes(primaryIndex,fit=true){selectedRoute=primaryIndex;layers.planned.clearLayers();layers.alternatives.clearLayers();plannedRoutes.forEach((r,i)=>{const layer=L.polyline(r.geometry,{color:i===primaryIndex?'#3c91e6':'#8997a2',weight:i===primaryIndex?6:3,opacity:i===primaryIndex?.95:.65,dashArray:i===primaryIndex?null:'7 9'}).addTo(i===primaryIndex?layers.planned:layers.alternatives);layer.bindTooltip(`${i===primaryIndex?'Rota principal':'Alternativa '+i}: ${formatDistance(r.distance)} · ${formatDuration(r.duration)}`);if(i!==primaryIndex)layer.on('click',()=>renderRoutes(i))});const r=plannedRoutes[primaryIndex];navigation.setRoute(r,$('destinationInput').value);window.dispatchEvent(new CustomEvent('rastreon:route-selected',{detail:{geometry:r.geometry}}));$('plannedDistance').textContent=formatDistance(r.distance);$('plannedDuration').textContent=formatDuration(r.duration);$('plannedArrival').textContent=new Date(Date.now()+r.duration*1000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});if(fit)map.fitBounds(L.latLngBounds(r.geometry),{padding:[30,30]});updateConsumption()}
async function loadVehicles(){const [references,owned]=await Promise.all([fetch('/api/vehicles/reference').then(r=>r.json()),fetch('/api/vehicles').then(r=>r.json())]);models=references;savedVehicles=owned.vehicles;$('referenceModel').innerHTML=models.map(m=>`<option value="${m.id}">${escapeHtml(m.brand)} ${escapeHtml(m.model)} ${escapeHtml(m.version)}</option>`).join('');if(!document.getElementById('vType')){$('referenceModel').closest('label').insertAdjacentHTML('afterend','<label class="field">Tipo de veículo<select id="vType"><option value="car">Carro</option><option value="motorcycle">Moto</option></select></label>')}if(savedVehicles.length){vehicle=savedVehicles.find(v=>v.selected)||savedVehicles[0];renderVehicleSummary();await loadFuelPrice()}else{vehicle=null;fuelPricePreference=null;applyModel(models[0]);renderFuelPrice();renderVehicleHud()}renderVehicleCards();await loadDevices()}
function ensureGeofencePanel(){if($('geofencePanel'))return;const panel=document.createElement('section');panel.id='geofencePanel';panel.className='card geofence-panel';panel.innerHTML='<div class="section-head"><div><span class="eyebrow">ZONA SEGURA</span><h2>Área de cobertura</h2></div></div><p class="muted-copy">Escolha o centro no mapa ou use a última posição recebida.</p><div class="geofence-form"><input id="geofenceName" placeholder="Nome, ex.: Casa"><input id="geofenceLat" type="number" step="any" placeholder="Latitude"><input id="geofenceLng" type="number" step="any" placeholder="Longitude"><select id="geofenceRadius"><option value="100">100 m</option><option value="250">250 m</option><option value="500" selected>500 m</option><option value="1000">1 km</option><option value="5000">5 km</option></select><button id="useGeofencePoint" class="secondary">Usar ponto atual</button><button id="saveGeofence">Salvar área</button></div><div id="geofenceList" class="geofence-list"></div>';$('vehiclesGrid').insertAdjacentElement('afterend',panel);$('useGeofencePoint').onclick=()=>{const point=positions.at(-1)||origin;if(!point)return toast('Selecione um ponto no mapa ou receba uma posição.');$('geofenceLat').value=point.latitude;$('geofenceLng').value=point.longitude};$('saveGeofence').onclick=saveGeofence}
async function loadGeofences(){ensureGeofencePanel();if(!vehicle?.id)return;const response=await fetch(`/api/vehicles/${vehicle.id}/geofences`),data=await response.json();if(!response.ok)return;layers.geofences.clearLayers();data.geofences.forEach(fence=>L.circle([fence.centerLat,fence.centerLng],{radius:fence.radiusMeters,color:'#ff5a0a',fillColor:'#ff5a0a',fillOpacity:.08,dashArray:'8 6'}).bindTooltip(`${fence.name} · ${formatDistance(fence.radiusMeters)}`).addTo(layers.geofences));$('geofenceList').innerHTML=data.geofences.length?data.geofences.map(fence=>`<div><span><b>${escapeHtml(fence.name)}</b><small>${formatDistance(fence.radiusMeters)}</small></span><button class="danger" data-remove-geofence="${fence.id}">Excluir</button></div>`).join(''):'<p class="muted-copy">Nenhuma área configurada.</p>';$('geofenceList').querySelectorAll('[data-remove-geofence]').forEach(button=>button.onclick=async()=>{await fetch(`/api/geofences/${button.dataset.removeGeofence}`,{method:'DELETE'});loadGeofences()})}
async function saveGeofence(){if(!vehicle?.id)return toast('Selecione um veículo.');const payload={name:$('geofenceName').value,type:'circle',centerLat:Number($('geofenceLat').value),centerLng:Number($('geofenceLng').value),radiusMeters:Number($('geofenceRadius').value),enabled:true},response=await fetch(`/api/vehicles/${vehicle.id}/geofences`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)return toast(data.error);toast('Área de cobertura salva.');loadGeofences()}
function applyModel(m){const fields={vBrand:m.brand,vModel:m.model,vVersion:m.version,vEngine:m.engine,vTransmission:m.transmission,vFuel:m.fuel,vCity:m.city,vRoad:m.road,vTank:m.tank||50};Object.entries(fields).forEach(([id,v])=>$(id).value=v||'');$('pbeSource').textContent=m.source==='manual'?'Consumo informado manualmente pelo usuário.':m.source}
function setVehicleFieldsReadonly(readonly){['vBrand','vModel','vYear','vVersion','vColor','vEngine','vTransmission','vFuel'].forEach(id=>{if($(id))$(id).readOnly=readonly});$('vehicleForm').classList.toggle('manual-vehicle-entry',!readonly)}
function renderVehicleLookupPreview(item){const preview=$('vehicleLookupPreview'),image=item.image||{url:'/images/vehicle-placeholder.svg',found:false};preview.classList.remove('hidden');preview.innerHTML=`<img alt="Imagem ilustrativa do modelo ${escapeHtml(item.make)} ${escapeHtml(item.model)}"><div><span class="eyebrow">VEÍCULO ENCONTRADO</span><h3>${escapeHtml(item.make)} ${escapeHtml(item.model)}</h3><p>${escapeHtml(item.version||'Versão não informada')}</p><dl><div><dt>Ano/modelo</dt><dd>${item.manufactureYear||'—'} / ${item.modelYear||'—'}</dd></div><div><dt>Cor</dt><dd>${escapeHtml(item.color||'—')}</dd></div><div><dt>Combustível</dt><dd>${escapeHtml(item.fuel||'—')}</dd></div><div><dt>Placa</dt><dd>${escapeHtml(item.plate)}</dd></div></dl><small>Imagem ilustrativa do modelo${image.attribution?` · ${escapeHtml(image.attribution)}`:''}</small></div>`;const img=preview.querySelector('img');img.src=image.url||'/images/vehicle-placeholder.svg';img.onerror=()=>{img.onerror=null;img.src='/images/vehicle-placeholder.svg'}}
function ensurePlateLookup(){if($('lookupPlateBtn'))return;const input=$('vPlate'),label=input.closest('label'),box=document.createElement('div');$('referenceModel').closest('label').classList.add('legacy-reference-model');$('vType')?.closest('label').classList.add('identified-vehicle-type');if(!$('vColor'))$('vFuel').closest('label').insertAdjacentHTML('afterend','<label>Cor<input id="vColor"></label>');setVehicleFieldsReadonly(true);box.className='plate-lookup';input.insertAdjacentElement('beforebegin',box);box.append(input);box.insertAdjacentHTML('beforeend','<button id="lookupPlateBtn" type="button">Buscar veículo</button>');label.insertAdjacentHTML('beforeend','<small id="plateLookupStatus" class="plate-lookup-status">Digite sua placa.</small><button id="manualVehicleBtn" type="button" class="text-btn hidden">Preencher manualmente</button>');label.insertAdjacentHTML('afterend','<section id="vehicleLookupPreview" class="vehicle-lookup-preview hidden"></section>');input.addEventListener('input',()=>{input.value=input.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,7);$('vehicleForm').dataset.lookupComplete='false';$('vehicleLookupPreview').classList.add('hidden')});$('lookupPlateBtn').onclick=lookupPlate;$('manualVehicleBtn').onclick=()=>{setVehicleFieldsReadonly(false);$('vehicleForm').dataset.lookupComplete='manual';$('manualVehicleBtn').classList.add('hidden');$('plateLookupStatus').textContent='Preencha os dados conhecidos. Nenhuma informação será inventada.'}}
async function lookupPlate(){const plate=$('vPlate').value.toUpperCase().replace(/[^A-Z0-9]/g,''),button=$('lookupPlateBtn'),status=$('plateLookupStatus'),manual=$('manualVehicleBtn');if(!/^[A-Z]{3}(?:[0-9]{4}|[0-9][A-Z][0-9]{2})$/.test(plate)){status.textContent='Confira a placa informada.';manual.classList.remove('hidden');return}button.disabled=true;button.textContent='Buscando…';status.textContent='Buscando veículo…';manual.classList.add('hidden');try{const response=await fetch(`/api/vehicles/lookup/${encodeURIComponent(plate)}`),data=await response.json();if(!response.ok){const error=new Error(data.error);error.code=data.code;throw error}const item=data.vehicle,reference=models.find(model=>normalizeText(model.brand)===normalizeText(item.make)&&normalizeText(item.model).includes(normalizeText(model.model)));if(reference)applyModel(reference);const normalizedType=/moto|motocicleta|ciclomotor|scooter/i.test(item.type||'')?'motorcycle':'car',fields={vPlate:item.plate,vBrand:item.make,vModel:item.model,vYear:item.modelYear,vVersion:item.version,vColor:item.color,vFuel:item.fuel,vType:normalizedType};Object.entries(fields).forEach(([id,value])=>{if(value!=null&&$(id))$(id).value=value});$('vehicleForm').dataset.lookupComplete='true';$('vehicleForm').dataset.manufactureYear=item.manufactureYear||'';$('vehicleForm').dataset.lookupImage=JSON.stringify(item.image||null);$('pbeSource').textContent=`vehicle-lookup:${item.provider||'cache'}`;setVehicleFieldsReadonly(true);renderVehicleLookupPreview(item);status.textContent=data.cached?'Dados recuperados do cache.':'Veículo encontrado. Confira antes de salvar.';toast('Veículo identificado pela placa.')}catch(error){$('vehicleForm').dataset.lookupComplete='false';status.textContent=error.code==='PLATE_NOT_FOUND'?'Não encontramos esse veículo. Você pode preencher os dados manualmente.':'Não foi possível consultar o veículo agora. Tente novamente.';manual.classList.remove('hidden');toast(status.textContent)}finally{button.disabled=false;button.textContent='Buscar veículo'}}
function renderVehicleSummary(){$('vehicleSummary').classList.remove('empty');$('vehicleSummary').innerHTML=`<b>${escapeHtml(vehicle.nickname)}</b> · ${escapeHtml(vehicle.plate||'sem placa')}<br>${escapeHtml(vehicle.brand)} ${escapeHtml(vehicle.model)} ${escapeHtml(vehicle.version)} · ${escapeHtml(vehicle.fuel)}`;renderVehicleHud();updateConsumption()}
function renderVehicleHud(){const hud=document.querySelector('.vehicle-hud');if(!hud)return;hud.querySelector('.vehicle-hud__visual')?.remove();const button=hud.querySelector('button');button.onclick=()=>document.querySelector('[data-view="vehicles"]')?.click();if(!vehicle){hud.querySelector('.vehicle-hud__model').textContent='Nenhum veículo cadastrado';hud.querySelector('.vehicle-hud__year').textContent='';hud.querySelector('.vehicle-hud__plate').textContent='';button.textContent='Cadastrar veículo';return}hud.querySelector('.vehicle-hud__title').textContent=vehicle.nickname||'Meu veículo';hud.querySelector('.vehicle-hud__model').textContent=`${vehicle.brand||''} ${vehicle.model||''}`.trim();hud.querySelector('.vehicle-hud__year').textContent=vehicle.year||'';hud.querySelector('.vehicle-hud__plate').textContent=vehicle.plate||'SEM PLACA';button.textContent='Ver detalhes';const image=hud.querySelector('.vehicle-hud__media img');if(image&&window.VehicleImageService)window.VehicleImageService.applyVehicleImage(image,vehicle);hud.classList.toggle('vehicle-identified',Boolean(vehicle.plate))}
function renderFuelPrice(){const input=$('fuelPriceInput'),source=$('fuelPriceSource');if(!input||!source)return;input.value=fuelPricePreference?.pricePerLiter??'';source.textContent=fuelPricePreference?`Fonte: ${fuelPricePreference.source==='user-provided'?'informado pelo usuário':fuelPricePreference.source}${fuelPricePreference.region?` · ${fuelPricePreference.region}`:''}`:'Fonte: não informada';updateConsumption()}
async function loadFuelPrice(){fuelPricePreference=null;if(!vehicle?.fuel)return renderFuelPrice();try{const response=await fetch(`/api/fuel-price?fuelType=${encodeURIComponent(vehicle.fuel)}`),data=await response.json();if(response.ok)fuelPricePreference=data.preference}catch{}renderFuelPrice()}
async function saveFuelPrice(){if(!vehicle?.fuel)return toast('Selecione um veículo com combustível informado.');const pricePerLiter=Number($('fuelPriceInput').value);if(!(pricePerLiter>0&&pricePerLiter<=100))return toast('Informe um preço válido por litro.');const response=await fetch('/api/fuel-price',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({fuelType:vehicle.fuel,pricePerLiter})}),data=await response.json();if(!response.ok)return toast(data.error);fuelPricePreference=data.preference;renderFuelPrice();toast('Preço salvo separadamente do veículo.')}
function vehiclePayload(){let image=null;try{image=JSON.parse($('vehicleForm').dataset.lookupImage||'null')}catch{}return{nickname:$('vNickname').value,type:$('vType')?.value||'car',plate:$('vPlate').value.toUpperCase(),brand:$('vBrand').value,model:$('vModel').value,year:Number($('vYear').value),manufactureYear:Number($('vehicleForm').dataset.manufactureYear)||null,version:$('vVersion').value,color:$('vColor')?.value||'',image,engine:$('vEngine').value,transmission:$('vTransmission').value,fuel:$('vFuel').value,city:Number($('vCity').value),road:Number($('vRoad').value),tank:Number($('vTank').value),dataSource:$('pbeSource').textContent||'manual',sourceDate:new Date().toISOString().slice(0,10)}}
async function saveVehicle(){if(!['true','manual'].includes($('vehicleForm').dataset.lookupComplete)&&!editingVehicleId)throw new Error('Busque a placa ou escolha o preenchimento manual.');const payload=vehiclePayload(),url=editingVehicleId?`/api/vehicles/${editingVehicleId}`:'/api/vehicles',method=editingVehicleId?'PUT':'POST';const res=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await res.json();if(!res.ok)throw new Error(data.error);vehicle=data.vehicle;editingVehicleId=null;$('vehicleDialog').close();await loadVehicles();toast('Veículo salvo no seu perfil.')}
function openVehicleForm(item=null){if(!item&&savedVehicles.length)return openAdditionalVehiclePlan();ensurePlateLookup();editingVehicleId=item?.id||null;$('vehicleForm').dataset.lookupComplete=item?'true':'false';$('vehicleLookupPreview').classList.add('hidden');$('manualVehicleBtn').classList.add('hidden');setVehicleFieldsReadonly(!item);if(item){const fields={vNickname:item.nickname,vPlate:item.plate,vBrand:item.brand,vModel:item.model,vYear:item.year,vVersion:item.version,vColor:item.color,vEngine:item.engine,vTransmission:item.transmission,vFuel:item.fuel,vCity:item.city,vRoad:item.road,vTank:item.tank,vType:item.type};Object.entries(fields).forEach(([id,value])=>{if($(id))$(id).value=value??''});$('vehicleForm').dataset.manufactureYear=item.manufactureYear||'';$('vehicleForm').dataset.lookupImage=JSON.stringify(item.image||null)}else{$('vehicleForm').reset();$('vNickname').value='Meu veículo';applyModel(models[0]);$('vehicleForm').dataset.manufactureYear='';$('vehicleForm').dataset.lookupImage=''}$('plateLookupStatus').textContent=item?'Dados salvos. Busque novamente para atualizar.':'Digite sua placa.';$('vehicleDialog').showModal()}
function openAdditionalVehiclePlan(){let dialog=$('additionalVehicleDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='additionalVehicleDialog';dialog.className='upgrade-dialog';dialog.innerHTML='<div class="modal-head"><div><span class="eyebrow">VEÍCULO ADICIONAL</span><h2>Proteja mais um veículo</h2></div><button type="button" class="icon-btn" data-close-upgrade>×</button></div><p class="upgrade-message">Para cadastrar outro veículo é necessário contratar um plano multi veículos. A solicitação e o envio de mais um aparelho rastreador já estão inclusos.</p><ul class="upgrade-benefits"><li>Novo rastreador incluso no plano</li><li>Acompanhamento de todos os veículos na mesma conta</li><li>Histórico e alertas individuais</li></ul><div class="dialog-actions"><button type="button" class="secondary" data-close-upgrade>Agora não</button><button type="button" data-view-plans>Ver planos disponíveis</button></div>';document.body.appendChild(dialog);dialog.querySelectorAll('[data-close-upgrade]').forEach(button=>button.onclick=()=>dialog.close());dialog.querySelector('[data-view-plans]').onclick=()=>{location.href='/#planos'}}dialog.showModal()}
function ensureFinesCard(){const layout=document.querySelector('#profileView .profile-layout');if(!layout||$('profileFinesCard'))return;const card=document.createElement('section');card.id='profileFinesCard';card.className='card fines-card';card.innerHTML='<div class="section-head"><div><span class="eyebrow">DOCUMENTOS DO VEÍCULO</span><h2>Multas</h2></div><span class="fines-status">Em dia</span></div><p class="muted-copy">Acompanhe notificações e vencimentos dos veículos cadastrados.</p><div class="empty-fines"><span>✓</span><div><b>Nenhuma multa encontrada</b><small>Quando houver uma notificação vinculada ao veículo, ela aparecerá aqui.</small></div></div><button type="button" class="secondary wide">Atualizar consulta</button>';card.querySelector('button').onclick=()=>toast('Consulta de multas atualizada. Nenhuma pendência encontrada.');layout.insertBefore(card,layout.querySelector('.privacy-card'))}
function renderVehicleCards(){const grid=$('vehiclesGrid');if(!grid)return;grid.innerHTML=savedVehicles.length?savedVehicles.map(v=>`<article class="vehicle-card ${v.selected?'selected':''}"><img class="vehicle-card-image" src="${escapeHtml(v.image?.url||'/images/vehicle-placeholder.svg')}" alt="Imagem ilustrativa de ${escapeHtml(v.brand)} ${escapeHtml(v.model)}"><div class="vehicle-card-head"><span class="vehicle-type">${v.type==='motorcycle'?'MOTO':'VEÍCULO'}</span>${v.selected?'<span class="badge online">Selecionado</span>':''}</div><h3>${escapeHtml(v.nickname)}</h3><p>${escapeHtml(v.brand)} ${escapeHtml(v.model)} ${escapeHtml(v.version)}</p><dl><div><dt>Ano</dt><dd>${v.manufactureYear||'—'} / ${v.year||'—'}</dd></div><div><dt>Placa</dt><dd>${escapeHtml(v.plate||'Não informada')}</dd></div><div><dt>Cor</dt><dd>${escapeHtml(v.color||'—')}</dd></div><div><dt>Combustível</dt><dd>${escapeHtml(v.fuel||'—')}</dd></div></dl>${v.image?.attribution?`<small class="image-credit">Créditos da imagem: ${escapeHtml(v.image.attribution)}</small>`:''}<div class="vehicle-actions">${v.selected?'':`<button data-select="${v.id}">Selecionar</button>`}<button class="secondary" data-edit="${v.id}">Editar</button><button class="danger" data-delete="${v.id}">Excluir</button></div></article>`).join(''):'<div class="empty-garage"><h3>Nenhum veículo cadastrado</h3><p>Adicione seu primeiro veículo para começar uma viagem.</p></div>';grid.querySelectorAll('.vehicle-card-image').forEach(img=>img.onerror=()=>{img.onerror=null;img.src='/images/vehicle-placeholder.svg'});grid.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>selectVehicle(Number(b.dataset.select)));grid.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openVehicleForm(savedVehicles.find(v=>v.id===Number(b.dataset.edit))));grid.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteVehicle(Number(b.dataset.delete)))}
function deviceState(device){if(device.status==='REVOKED')return{key:'revoked',label:'Revogado'};if(!device.lastSeen)return{key:'offline',label:'Nunca conectado'};const age=Date.now()-device.lastSeen;if(age<=120000)return{key:'online',label:'Online'};if(age<=600000)return{key:'stale',label:'Sem atualização'};return{key:'offline',label:'Offline'}}
async function loadDevices(){const list=$('devicesList');if(!list)return;if(!vehicle?.id){list.innerHTML='<div class="empty-state">Cadastre e selecione um veículo.</div>';return}const response=await fetch(`/api/vehicles/${vehicle.id}/devices`),data=await response.json();if(!response.ok){list.innerHTML='<div class="empty-state">Não foi possível carregar os dispositivos.</div>';return}list.innerHTML=data.devices.length?data.devices.map(device=>{const state=deviceState(device);return`<article class="device-row"><span class="device-symbol">${device.type==='PHONE'?'▣':'●'}</span><div><b>${escapeHtml(device.name)}</b><small>${device.lastSeen?`Último contato: ${new Date(device.lastSeen).toLocaleString('pt-BR')}`:'Ainda não realizou conexão GPS'}</small></div><span class="device-status ${state.key}">● ${state.label}</span>${device.status==='ACTIVE'?`<button class="danger" data-revoke-device="${device.id}">Desvincular</button>`:''}</article>`}).join(''):'<div class="empty-state">Nenhum rastreador vinculado a este veículo.</div>';list.querySelectorAll('[data-revoke-device]').forEach(button=>button.onclick=()=>revokeDevice(button.dataset.revokeDevice))}
async function revokeDevice(id){if(!confirm('Desvincular este celular? Ele deixará de enviar localização imediatamente.'))return;const response=await fetch(`/api/devices/${id}`,{method:'DELETE'});if(!response.ok){const data=await response.json();return toast(data.error||'Não foi possível desvincular.')}await loadDevices();toast('Celular desvinculado.')}
async function connectSelectedPhone(){if(!vehicle?.id)return toast('Cadastre e selecione um veículo.');document.querySelector('[data-view="tracking"]').click();document.body.classList.add('trip-planning');await createSession()}
async function selectVehicle(id){const res=await fetch(`/api/vehicles/${id}/select`,{method:'POST'});if(!res.ok)return toast('Não foi possível selecionar o veículo.');await loadVehicles();toast('Veículo selecionado para a viagem.')}
async function deleteVehicle(id){if(!confirm('Excluir este veículo?'))return;const res=await fetch(`/api/vehicles/${id}`,{method:'DELETE'});if(!res.ok)return toast('Não foi possível excluir o veículo.');await loadVehicles();toast('Veículo excluído.')}
function ensureProfileAvatarEditor(){const avatar=$('profileInitial');if(!avatar||$('profileAvatarInput'))return;avatar.classList.add('editable-avatar');avatar.setAttribute('role','button');avatar.setAttribute('tabindex','0');avatar.setAttribute('aria-label','Alterar foto de perfil');avatar.insertAdjacentHTML('afterend','<input id="profileAvatarInput" type="file" accept="image/jpeg,image/png,image/webp" hidden><button id="changeAvatarBtn" type="button" class="text-btn profile-avatar-action">Alterar foto</button>');const open=()=>$('profileAvatarInput').click();avatar.onclick=open;avatar.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}};$('changeAvatarBtn').onclick=open;$('profileAvatarInput').onchange=event=>saveProfileAvatar(event.target.files?.[0])}
function resizeProfileAvatar(file){return new Promise((resolve,reject)=>{if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type))return reject(new Error('Escolha uma imagem JPG, PNG ou WebP.'));if(file.size>8*1024*1024)return reject(new Error('A imagem deve ter no máximo 8 MB.'));const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{URL.revokeObjectURL(url);const size=Math.min(image.naturalWidth,image.naturalHeight),sx=(image.naturalWidth-size)/2,sy=(image.naturalHeight-size)/2,canvas=document.createElement('canvas');canvas.width=canvas.height=192;canvas.getContext('2d').drawImage(image,sx,sy,size,size,0,0,192,192);let quality=.82,data=canvas.toDataURL('image/jpeg',quality);while(data.length>44000&&quality>.42){quality-=.08;data=canvas.toDataURL('image/jpeg',quality)}resolve(data)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Não foi possível abrir essa imagem.'))};image.src=url})}
function renderProfileAvatar(avatarData,name){const avatar=$('profileInitial');if(!avatar)return;avatar.classList.toggle('has-photo',Boolean(avatarData));avatar.style.backgroundImage=avatarData?`url(${avatarData})`:'';avatar.textContent=avatarData?'':String(name||'U').slice(0,1).toUpperCase()}
async function saveProfileAvatar(file){if(!file)return;const button=$('changeAvatarBtn');button.disabled=true;button.textContent='Salvando…';try{const avatarData=await resizeProfileAvatar(file),csrfResponse=await fetch('/api/auth/csrf'),csrf=await csrfResponse.json();if(!csrfResponse.ok)throw new Error(csrf.error);const response=await fetch('/api/profile/avatar',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.token},body:JSON.stringify({avatarData})}),data=await response.json();if(!response.ok)throw new Error(data.error);renderProfileAvatar(data.avatarData,$('profileName').textContent);toast('Foto de perfil atualizada.')}catch(error){toast(error.message||'Não foi possível atualizar a foto.')}finally{button.disabled=false;button.textContent='Alterar foto';$('profileAvatarInput').value=''}}
async function loadProfile(){ensureProfileAvatarEditor();const res=await fetch('/api/profile'),data=await res.json();if(!res.ok)return;$('profileName').textContent=data.user.name;$('profileEmail').textContent=data.user.email;renderProfileAvatar(data.user.avatarData,data.user.name);$('profileCreated').textContent=new Date(data.user.createdAt).toLocaleDateString('pt-BR');$('profilePlan').textContent=data.plan;$('profileVehicleCount').textContent=data.vehicleCount;$('profileAlertCount').textContent=data.recentAlertCount;$('profileTrips').innerHTML=data.recentTrips.length?data.recentTrips.map(t=>`<div class="profile-trip"><b>${escapeHtml(t.vehicle?.nickname||'Veículo')}</b><span>${new Date(t.createdAt).toLocaleString('pt-BR')}</span><small>${t.closedAt?'Finalizada':'Em aberto'}</small></div>`).join(''):'<div class="empty-state">Nenhuma viagem registrada.</div>'}
async function exportPrivacyData(){const button=$('exportDataBtn');button.disabled=true;try{const response=await fetch('/api/privacy/export');if(!response.ok){const data=await response.json();throw new Error(data.error||'Não foi possível exportar os dados.')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`rastreon-dados-${new Date().toISOString().slice(0,10)}.json`;document.body.append(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Arquivo de dados gerado com segurança.')}catch(error){toast(error.message)}finally{button.disabled=false}}
async function changePassword(){const currentPassword=$('changeCurrentPassword').value,newPassword=$('changeNewPassword').value,button=$('changePasswordBtn');if(!currentPassword||!newPassword)return toast('Preencha a senha atual e a nova senha.');button.disabled=true;try{const csrfResponse=await fetch('/api/auth/csrf'),csrfData=await csrfResponse.json();if(!csrfResponse.ok)throw new Error(csrfData.error);const response=await fetch('/api/auth/password',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfData.token},body:JSON.stringify({currentPassword,newPassword})});if(!response.ok){const data=await response.json();throw new Error(data.error)}$('changeCurrentPassword').value='';$('changeNewPassword').value='';toast('Senha atualizada. Outras sessões foram encerradas.')}catch(error){toast(error.message||'Não foi possível alterar a senha.')}finally{button.disabled=false}}
async function deletePrivacyAccount(){const password=$('privacyPassword').value,confirmation=$('deleteConfirmation').value;if(!password)return toast('Informe sua senha atual.');if(confirmation!=='EXCLUIR MINHA CONTA')return toast('Digite a frase de confirmação exatamente como exibida.');if(!confirm('Esta ação é permanente. Deseja realmente excluir a conta e todos os dados associados?'))return;const button=$('deleteAccountBtn');button.disabled=true;try{const csrfResponse=await fetch('/api/auth/csrf'),csrfData=await csrfResponse.json();if(!csrfResponse.ok)throw new Error(csrfData.error||'Não foi possível validar esta operação.');const response=await fetch('/api/privacy/account',{method:'DELETE',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfData.token},body:JSON.stringify({password,confirmation})});if(!response.ok){const data=await response.json();throw new Error(data.error||'Não foi possível excluir a conta.')}location.replace('/login.html')}catch(error){toast(error.message);button.disabled=false}}
async function createSession(){if(!vehicle){openVehicleForm();toast('Configure o veículo antes de criar a sessão.');return null}try{const res=await fetch('/api/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vehicleId:vehicle.id})}),d=await res.json();if(!res.ok)throw new Error(d.error);sessionId=d.id;pairingId=d.pairingId;mobileUrl=d.pairUrl;$('qrImage').src=d.qrCode;$('sessionCode').textContent=d.pairingCode;$('sessionCode').parentElement.firstChild.textContent='Código ';let instructions=$('manualMobileInstructions');if(!instructions){instructions=document.createElement('small');instructions.id='manualMobileInstructions';$('sessionCode').parentElement.insertAdjacentElement('afterend',instructions)}const renderExpiry=()=>{const remaining=Math.max(0,d.pairingExpiresAt-Date.now()),minutes=Math.floor(remaining/60000),seconds=Math.floor(remaining%60000/1000);instructions.textContent=remaining?`No celular, abra ${new URL(d.pairUrl).origin}/pair e leia o QR ou digite o código. Expira em ${minutes}:${String(seconds).padStart(2,'0')}.`:'QR Code expirado. Gere uma nova sessão.';if(!remaining){clearInterval(pairingTimer);$('phoneStatus').textContent='● QR expirado'}};clearInterval(pairingTimer);renderExpiry();pairingTimer=setInterval(renderExpiry,1000);$('sessionEmpty').classList.add('hidden');$('sessionActive').classList.remove('hidden');$('clearBtn').disabled=false;$('closeBtn').disabled=false;socket.emit('session:join',{sessionId,role:'dashboard'});toast('QR seguro criado. Aguardando leitura no celular.');return d}catch(e){toast(e.message||'Não foi possível criar a sessão.');return null}}
function ensureTrackerPairing(){const actions=document.querySelector('.map-toolbar .actions');if(!actions||$('trackerPairBtn'))return;const button=document.createElement('button');button.id='trackerPairBtn';button.className='secondary';button.textContent='Rastreador';button.title='Conectar celular como rastreador';button.onclick=()=>openTrackerPairing(false);actions.appendChild(button)}
async function openTrackerPairing(forceNew=false){let dialog=$('trackerPairDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='trackerPairDialog';dialog.className='tracker-pair-dialog';dialog.innerHTML='<div class="modal-head"><div><span class="eyebrow">OPÇÃO PARA CELULAR</span><h2>Levar a viagem no celular</h2></div><button type="button" class="icon-btn" data-close-tracker>×</button></div><p class="tracker-intro">Esta etapa é opcional. Leia o QR Code para acompanhar o teste da viagem no celular; a navegação deste site funciona de forma independente.</p><div class="tracker-qr-state"><img alt="QR Code para abrir a viagem no celular"><strong>Preparando QR Code…</strong><small></small></div><button type="button" class="secondary wide" data-new-tracker>Gerar novo QR Code</button>';document.body.appendChild(dialog);dialog.querySelector('[data-close-tracker]').onclick=()=>dialog.close();dialog.querySelector('[data-new-tracker]').onclick=()=>openTrackerPairing(true)}dialog.showModal();const image=dialog.querySelector('img'),code=dialog.querySelector('strong'),note=dialog.querySelector('small');if(!vehicle){code.textContent='Cadastre um veículo primeiro';note.textContent='Abra a aba Veículos e informe a placa.';image.removeAttribute('src');return}if(!forceNew&&sessionId&&$('qrImage').src){image.src=$('qrImage').src;code.textContent=`Código ${$('sessionCode').textContent}`;note.textContent='Leia o QR Code para abrir a sessão desta viagem no celular.';return}code.textContent='Gerando QR Code seguro…';note.textContent='';const data=await createSession();if(!data)return;image.src=data.qrCode;code.textContent=`Código ${data.pairingCode}`;note.textContent=`Expira em ${data.pairingExpiresInMinutes} minutos. O compartilhamento é opcional e não bloqueia a navegação no site.`}
async function startTrip(){if(!plannedRoutes.length)return toast('Calcule uma rota antes de iniciar.');if(!sessionId)return toast('Crie uma sessão de rastreamento antes de iniciar.');if(!tripStart){tripStart=Date.now();tripEnd=null;try{const response=await fetch('/api/trips',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({trackingSessionId:sessionId,vehicleId:vehicle.id,plannedRoute:plannedRoutes[selectedRoute],startedAt:tripStart})}),data=await response.json();if(!response.ok)throw new Error(data.error);tripId=data.trip.id;$('tripStarted').textContent=new Date(tripStart).toLocaleString('pt-BR');$('startTripBtn').textContent='Finalizar viagem';navigation.start();addEvent('Viagem iniciada',`${vehicle.nickname} · rota planejada preservada`);socket.emit('trip:update',{startedAt:tripStart,route:plannedRoutes[selectedRoute],vehicle});checkSchedule()}catch(error){tripStart=null;toast(error.message)}}else{tripEnd=Date.now();if(tripId){const response=await fetch(`/api/trips/${tripId}/finish`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({endedAt:tripEnd})});if(!response.ok)return toast('Não foi possível finalizar a viagem.')}navigation.stop();$('tripEnded').textContent=new Date(tripEnd).toLocaleString('pt-BR');$('startTripBtn').textContent='Viagem finalizada';$('startTripBtn').disabled=true;addEvent('Viagem finalizada',`Distância total estimada: ${formatDistance(confirmedMeters+rebuiltMeters)}`);updateTimeline()}}
async function loadTripHistory(){const response=await fetch('/api/trips'),data=await response.json();historyTrip=null;$('replayTripBtn').disabled=true;if(!response.ok||!data.trips.length)return;const latest=await fetch(`/api/trips/${data.trips[0].id}`).then(r=>r.json()).then(value=>value.trip);historyTrip=latest;$('replayTripBtn').disabled=!Array.isArray(latest.actualTrack)||latest.actualTrack.length<2;$('tripStarted').textContent=new Date(latest.startedAt).toLocaleString('pt-BR');$('tripEnded').textContent=latest.endedAt?new Date(latest.endedAt).toLocaleString('pt-BR'):'Em andamento';$('tripDuration').textContent=formatDuration(latest.comparison.actualDurationSeconds);$('movingTime').textContent=formatDuration(latest.comparison.movingSeconds);$('stoppedTime').textContent=formatDuration(latest.comparison.stoppedSeconds);const comparison=`Planejado: ${formatDistance(latest.comparison.plannedDistanceMeters)} · realizado: ${formatDistance(latest.comparison.actualDistanceMeters)} · diferença: ${formatDistance(Math.abs(latest.comparison.distanceDifferenceMeters))}`;$('eventTimeline').innerHTML=`<div class="event-item"><b>Comparação da última viagem</b><small>${comparison}</small></div>`+latest.interruptions.map(item=>`<div class="event-item alert"><b>Interrupção de conexão</b><small>${formatDuration((item.duration||0)/1000)} · ${escapeHtml(item.classification)}</small></div>`).join('')}
function stopTripReplay({clear=true}={}){if(replayTimer)clearInterval(replayTimer);replayTimer=null;replayMarker=null;replayIndex=0;if(clear){layers.replay.clearLayers();$('replayBadge').classList.add('hidden')}}
function playTripHistory(){const track=historyTrip?.actualTrack;if(!Array.isArray(track)||track.length<2)return toast('Esta viagem não possui pontos suficientes para reprodução.');stopTripReplay();document.querySelector('[data-view="tracking"]')?.click();$('replayBadge').classList.remove('hidden');$('replayProgress').textContent=`1 de ${track.length} pontos históricos`;const geometry=track.map(point=>[point.latitude,point.longitude]),replayIcon=L.divIcon({className:'replay-vehicle-icon',html:'<span aria-label="Veículo em reprodução">R</span>'});L.polyline(geometry,{color:'#7d3fe0',weight:5,opacity:.75,dashArray:'7 7'}).addTo(layers.replay);replayMarker=L.marker(geometry[0],{icon:replayIcon}).addTo(layers.replay).bindTooltip('REPRODUÇÃO — não é ao vivo');map.fitBounds(L.latLngBounds(geometry),{padding:[35,35]});replayIndex=0;replayTimer=setInterval(()=>{replayIndex++;if(replayIndex>=track.length){clearInterval(replayTimer);replayTimer=null;$('replayProgress').textContent=`Concluída · ${track.length} pontos históricos`;return}replayMarker.setLatLng(geometry[replayIndex]);$('replayProgress').textContent=`${replayIndex+1} de ${track.length} pontos históricos`},450)}
function checkSchedule(){if(!$('scheduleEnabled').checked)return;const now=new Date(),weekday=now.getDay(),time=now.toTimeString().slice(0,5),outside=weekday===0||weekday===6||time<$('allowedFrom').value||time>$('allowedTo').value;$('scheduleAlert').classList.toggle('hidden',!outside);if(outside)addEvent('Uso fora do horário permitido',`Regra: ${$('allowedFrom').value} às ${$('allowedTo').value}`,true)}
