function updateConsumption(){if(!vehicle)return;const distanceMeters=plannedRoutes[selectedRoute]?.distance||confirmedMeters+rebuiltMeters,urbanShare=.55,totalKm=distanceMeters/1000,urbanKm=totalKm*urbanShare,roadKm=totalKm-urbanKm,urbanLiters=urbanKm/vehicle.city,roadLiters=roadKm/vehicle.road,idleLiters=stoppedMs/3600000*.8,base=urbanLiters+roadLiters+idleLiters,min=base*.92,max=base*1.18,price=fuelPricePreference?.pricePerLiter,pctMin=vehicle.tank?min/vehicle.tank*100:0,pctMax=vehicle.tank?max/vehicle.tank*100:0;$('fuelMin').textContent=br(min,2);$('fuelMax').textContent=br(max,2);$('fuelCostLine').textContent=price?`R$ ${br(min*price,2)}–${br(max*price,2)} · preço ${fuelPricePreference.source==='user-provided'?'informado':fuelPricePreference.source}`:'Custo indisponível sem preço informado';$('tankUse').style.width=`${Math.min(100,pctMax)}%`;$('tankText').textContent=`≈ ${br(pctMin)}% – ${br(pctMax)}% do tanque`;let details=$('fuelBreakdown');if(!details){details=document.createElement('dl');details.id='fuelBreakdown';details.className='fuel-breakdown';document.querySelector('.consumption .range').insertAdjacentElement('afterend',details)}details.innerHTML=`<div><dt>Consumo urbano</dt><dd>${br(vehicle.city)} km/L</dd></div><div><dt>Consumo rodoviário</dt><dd>${br(vehicle.road)} km/L</dd></div><div><dt>Distância urbana estimada</dt><dd>${br(urbanKm,2)} km</dd></div><div><dt>Distância rodoviária estimada</dt><dd>${br(roadKm,2)} km</dd></div>`}
